                      WAWebProtobufsE2E.PeerDataOperationRequestMessage.SyncDCollectionFatalRecoveryRequest.decode!(
                        delimited
                      )

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsE2E.PeerDataOperationRequestMessage.SyncDCollectionFatalRecoveryRequest.decode!(
                          delimited
                        )
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"2", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | fullHistorySyncOnDemandRequest:
                  case :erlang.map_get(:fullHistorySyncOnDemandRequest, msg) do
                    nil ->
                      WAWebProtobufsE2E.PeerDataOperationRequestMessage.FullHistorySyncOnDemandRequest.decode!(
                        delimited
                      )

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsE2E.PeerDataOperationRequestMessage.FullHistorySyncOnDemandRequest.decode!(
                          delimited
                        )
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"*", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | placeholderMessageResendRequest: [
                  WAWebProtobufsE2E.PeerDataOperationRequestMessage.PlaceholderMessageResendRequest.decode!(
                    delimited
                  )
                  | :erlang.map_get(:placeholderMessageResendRequest, msg)
                ]
            }

            parse_key_value(rest, msg)

          <<"\"", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | historySyncOnDemandRequest:
                  case :erlang.map_get(:historySyncOnDemandRequest, msg) do
                    nil ->
                      WAWebProtobufsE2E.PeerDataOperationRequestMessage.HistorySyncOnDemandRequest.decode!(
                        delimited
                      )

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        WAWebProtobufsE2E.PeerDataOperationRequestMessage.HistorySyncOnDemandRequest.decode!(
                          delimited
                        )
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"\x1A", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | requestURLPreview: [
                  WAWebProtobufsE2E.PeerDataOperationRequestMessage.RequestUrlPreview.decode!(
                    delimited
                  )
                  | :erlang.map_get(:requestURLPreview, msg)
                ]
            }

            parse_key_value(rest, msg)

          <<"\x12", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | requestStickerReupload: [
                  WAWebProtobufsE2E.PeerDataOperationRequestMessage.RequestStickerReupload.decode!(
                    delimited
                  )
                  | :erlang.map_get(:requestStickerReupload, msg)
                ]
            }

            parse_key_value(rest, msg)

          <<"\b", 0::1, varint_value::7, rest::binary>> ->
            value = WAWebProtobufsE2E.PeerDataOperationRequestType.decode(varint_value)
            msg = %{msg | peerDataOperationRequestType: value}
            parse_key_value(rest, msg)

          <<"\b", bytes::binary>> ->
            {value, rest} =
              Protox.Decode.parse_enum(bytes, WAWebProtobufsE2E.PeerDataOperationRequestType)

            msg = %{msg | peerDataOperationRequestType: value}
            parse_key_value(rest, msg)

          <<bytes::binary>> ->
            {tag, wire_type, rest} = Protox.Decode.parse_key(bytes)
            {value, rest} = Protox.Decode.parse_unknown(tag, wire_type, rest)
            msg = %{msg | __uf__: [value | :erlang.map_get(:__uf__, msg)]}
            parse_key_value(rest, msg)
        end
      end
    )
  )

  (
    @spec unknown_fields(struct()) :: [{non_neg_integer(), Protox.Types.tag(), binary()}]
    def unknown_fields(msg), do: msg.__uf__

    @spec unknown_fields_name() :: :__uf__
    def unknown_fields_name(), do: :__uf__

    @spec clear_unknown_fields(struct) :: struct
    def clear_unknown_fields(msg), do: struct!(msg, __uf__: [])
  )

  (
    @spec default(atom()) ::
            {:ok, Protox.Scalar.scalar_default_value_type()}
            | {:error, :no_such_field | :no_default_value}
    def default(field_name), do: Protox.MessageSchema.default(@schema, field_name)
  )
end
